      actorId: actor.userId,
      action: "payment.voided",
      entityId: payment.id,
      details: {
        leaseId: payment.lease_id,
        amountSen: toSafeNumber(payment.amount_sen),
        reason,
        allocationsRemoved: removed.count,
      },
    });
    return { status: "voided" as const };
  }, TRANSACTION_OPTIONS);

